package com.asmj.marketplace.job.repository; import com.asmj.marketplace.job.model.JobOffer; import org.springframework.data.mongodb.repository.MongoRepository; import java.util.*; public interface JobOfferRepository extends MongoRepository<JobOffer,String>{List<JobOffer> findByCandidateIdOrderByCreatedAtDesc(String candidateId); List<JobOffer> findByVendorIdOrderByCreatedAtDesc(String vendorId); Optional<JobOffer> findByApplicationId(String applicationId);}
